import pickle

def serialize(obj):
    return pickle.dumps(obj)

def deserialize(data):
    return pickle.loads(data)

class Game:
    def __init__(self, name, score):
        self.name = name
        self.score = score

    def add_points(self, points):
        self.score += points

game = Game("Pong", 100)

serialized_game = serialize(game)
deserialized_game = deserialize(serialized_game)

deserialized_game.add_points(50)

print(deserialized_game.score)

import pickle

class Car:
    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year

class CarSerializer:
    def serialize(self, obj):
        return pickle.dumps(obj)

    def deserialize(self, data):
        return pickle.loads(data)

def handle_request(data):
    serializer = CarSerializer()
    car = serializer.deserialize(data)

    html = f"""
    <h1>{car.make} {car.model}</h1>
    <p>year: {car.year}</p>
    """
    return html

def main():
    data = b"abc"
    request = handle_request(data)

    print(request)

if __name__ == "__main__":
    main()

