import pickle

class User:
    def __init__(self, name, age):
        self.name = name
        self.age = age

def save_user(user):
    with open('user.pkl', 'wb') as f:
        pickle.dump(user, f)

def load_user():
    with open('user.pkl', 'rb') as f:
        return pickle.load(f)

user = User('Alice', 30)
save_user(user)
user = load_user()

